
const PLAN={"stay":{"name":"Stay Present","price":399,"total":12,"reels":6,"carousels":4,"memes":2,"frequency":"3 posts per week"},"daily":{"name":"Daily Authority","price":799,"total":28,"reels":12,"carousels":8,"memes":8,"frequency":"1 post every day"},"maximum":{"name":"Maximum Visibility","price":999,"total":64,"reels":24,"carousels":20,"memes":20,"frequency":"2 posts most days, 3 on Tue & Wed"}};
const SOURCE={"own":{"name":"You Record, We Create","price":0,"description":"Upload existing footage, interviews and approved materials."},"guided":{"name":"We Plan, You Record","price":500,"description":"Monthly editorial themes, up to 8 scripts, hooks and guidance."},"interview":{"name":"We Interview, We Create","price":1000,"description":"Editorial planning and up to 2 guided remote interviews."}};
const STYLE={"clean":{"name":"Clean & Professional","price":0,"description":"Professional editing, branded templates, captions and selective simple B-roll."},"dynamic":{"name":"Dynamic & Engaging","price":199,"description":"4 selected Reels get dynamic motion, stronger pacing and enhanced B-roll."},"cinematic":{"name":"Cinematic & Premium","price":399,"description":"4 selected Reels get advanced X-roll, design, effects and cinematic sound."}};

const $=id=>document.getElementById(id);
const money=n=>'$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEFAULT_STATE={plan:'maximum',source:'interview',style:'dynamic',scenario:'doctor'};
let state={...DEFAULT_STATE}, workspace={costs:{},production:{},checks:[],batches:['Pendiente','Pendiente','Pendiente','Pendiente'],journal:[]};
let storageOK=true;function readStore(k){try{return localStorage.getItem(k)}catch{storageOK=false;return null}}function putStore(k,v){try{localStorage.setItem(k,v)}catch{storageOK=false;toast('No fue posible guardar en este navegador. Exporta tus datos.')}}
function toast(s){$('toast').textContent=s;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').textContent='',5000)}
function go(id){const el=$(id);if(!el||!el.classList.contains('internal'))return;document.body.classList.remove('clientmode');document.querySelectorAll('.section').forEach(n=>n.classList.remove('active'));el.classList.add('active');document.querySelectorAll('.nav button').forEach(b=>{b.classList.toggle('active',b.dataset.target===id);b.setAttribute('aria-current',b.dataset.target===id?'page':'false')});$('internalBtn').classList.add('active');$('clientBtn').classList.remove('active');history.replaceState(null,'','#'+id);closeMenu();window.scrollTo(0,0);el.querySelector('h1')?.setAttribute('tabindex','-1');if(document.readyState==='complete')el.querySelector('h1')?.focus({preventScroll:true});if(id==='proposal')renderProposal();}
function clientGo(id){const el=$(id);if(!el||!el.classList.contains('client-page'))return;document.querySelectorAll('.section').forEach(n=>n.classList.remove('active'));el.classList.add('active');document.querySelectorAll('.client-subnav button').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')?.includes(id)));history.replaceState(null,'','#'+id);window.scrollTo(0,0);if(id==='clientProposal')renderClientProposal();el.querySelector('h1')?.setAttribute('tabindex','-1');if(document.readyState==='complete')el.querySelector('h1')?.focus({preventScroll:true});}
function setMode(mode){const c=mode==='client';document.body.classList.toggle('clientmode',c);$('internalBtn')?.classList.toggle('active',!c);$('clientBtn')?.classList.toggle('active',c);closeMenu();if(c)clientGo('clientLanding');else go('home')}
function closeMenu(){if(innerWidth<=800)$('studio-sidebar')?.style.removeProperty('display');$('menuToggle')?.setAttribute('aria-expanded','false')}
function toggleMenu(){const open=$('menuToggle').getAttribute('aria-expanded')==='true';$('menuToggle').setAttribute('aria-expanded',String(!open));$('studio-sidebar').style.display=open?'none':'block'}
function quote(){return PLAN[state.plan].price+SOURCE[state.source].price+STYLE[state.style].price}
function validState(s){return s&&Object.keys(PLAN).includes(s.plan)&&Object.keys(SOURCE).includes(s.source)&&Object.keys(STYLE).includes(s.style)&&['doctor','lawyer','consultant','clinic','podcaster'].includes(s.scenario)}
function saveState(){putStore('silverwing_atelier_02',JSON.stringify({version:2,state,workspace,tariffs:tariffData(),prospect:$('prospect')?.value||''}));}
function download(content,name,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function toggleMaterial(){document.body.classList.toggle('solid-material');toast(document.body.classList.contains('solid-material')?'Matériau sólido activado':'Vidrio activado')}
const quick=[['¿Qué ofrecemos exactamente?','services','▤','Explora cada servicio, su propósito y sus límites.'],['¿Por qué vendemos estos planes?','strategy','◎','Conecta hipótesis, capacidad y decisiones de producto.'],['¿Qué le recomiendo a un doctor?','scenarios','♧','Simula una propuesta para un cliente ocupado.'],['¿Cuánto debería cobrar?','builder','▦','Configura frecuencia, creación y calidad visual.'],['¿Nos deja un margen suficiente?','finance','∑','Calcula contribución estimada por paquete.'],['¿Cuándo entregamos el contenido?','operations','◷','Consulta el calendario y los acuerdos de entrega.'],['¿Cómo presento Silverwing?','sales','◇','Preguntas, argumentos y objeciones comerciales.'],['¿Qué recibe Inner Circle?','club','♛','Beneficios incluidos y experiencias opcionales.'],['¿Qué nuevo servicio podemos crear?','innovation','✦','Evalúa oportunidades antes de lanzarlas.'],['¿Cómo ve esto el cliente?','client','↗','Abre la experiencia comercial premium.']];$('quickTiles').innerHTML=quick.map(x=>`<button class="tile" onclick="${x[1]==='client'?"setMode('client')":"go('"+x[1]+"')"}"><span class="icon">${x[2]}</span><span><strong>${x[0]}</strong><em>${x[3]}</em></span></button>`).join('');
const principles=[['Volume creates opportunities','Más publicaciones útiles generan más experimentos de mensajes.','No hay garantía de alcance o viralidad. Se mide respuesta real.'],['Multiple formats, different jobs','Reels para descubrimiento; carouseles para explicar; memes y visuales para conexión y compartidos.','La mezcla se ajusta por sector, plataforma y resultados.'],['Human judgment + AI velocity','IA, plantillas y batch editing reducen repetición; el criterio humano asegura claridad, tono y precisión.','No vender ediciones automáticas como si fueran dirección creativa.'],['Less client effort is more value','Los profesionales no deberían necesitar volverse estrategas o editores.','Material existente, guiones o entrevistas según disponibilidad.'],['Premium is a finish, not unlimited labor','Los upgrades visuales transforman los momentos de mayor potencial.','El número de piezas premium queda definido por ciclo.'],['Inner Circle increases belonging','Una membresía incluida crea formación, acceso y continuidad.','Medir uso real y evitar beneficios no disponibles.']];$('principles').innerHTML=principles.map(x=>`<div class="card"><span class="tag">Principle</span><h3 style="margin-top:13px">${x[0]}</h3><p>${x[1]}</p><p class="muted small"><b>Regla:</b> ${x[2]}</p></div>`).join('');
const services=[['Short-form Reels','Reaprovechar conocimiento con distribución en video','Momentos elegidos, subtítulos, audio, hooks y edición 9:16','Material autorizado de entrevistas, clases o videos','Duración y rondas de revisión definidas'],['Carousels educativos','Descomponer ideas complejas y favorecer comprensión','Secuencia visual multislide, narrativa, diseño, CTA cuando corresponde','Transcripciones, briefs, datos aprobados','Máximo de diapositivas por pieza a definir'],['Memes y visuales estáticos','Variar el ritmo del calendario y producir piezas compartibles','Creatividades de marca, humor apropiado, frases y microexplicaciones','Ideas, fotos, banco visual o IA','Nunca forzar humor en temas sensibles'],['AI Creative Studio','Crear escenas y explicaciones sin necesidad de grabación nueva','Imágenes IA, animaciones, video IA, visuales para carruseles','Mensajes y materiales de referencia aprobados','No simular resultados reales ni afirmaciones no verificadas'],['Clean / Dynamic / Cinematic','Permitir que el cliente mejore el resultado estético','Desde edición estándar hasta X-roll, efectos y audio cinematográfico','Clip base usable y brief visual','Dynamic y Cinematic se aplican a 4 Reels/ciclo'],['Content Brain / Scripts','Eliminar el bloqueo de ideación y planificación','Temas, estructura de guiones, hooks, dirección de grabación','Expertise del cliente y objetivos editoriales','Hasta 8 guiones/ciclo Guided; el experto valida afirmaciones'],['Guided Remote Interviews','Extraer ideas sin exigir grabación autónoma','Preparación de preguntas, coordinación y sesión remota','Disponibilidad y conocimiento del cliente','Hasta 2 sesiones de 45–60 min/ciclo'],['Podcast Studio','Crear un activo de contenido largo recurrente','Edición episodio, limpieza, título, portada, notas y opciones de distribución','Grabaciones del cliente o entrevista remota','Servicio opcional separado; no incluye estudio físico'],['Inner Circle Membership','Fomentar formación, relación y compras complementarias','Comunidad, recursos, sesiones, perks y acceso a servicios especiales','Suscripción activa','Servicios avanzados pueden tener costo']];$('serviceGrid').innerHTML=services.map(x=>`<article class="service"><h3>${x[0]}</h3><p>${x[1]}</p><details><summary>Ver ficha operativa y criterios ↓</summary><p><b>Entregamos:</b> ${x[2]}</p><p><b>Insumos:</b> ${x[3]}</p><p><b>Límites:</b> ${x[4]}</p></details></article>`).join('');
const innovations=[['Podcast production','$399–$1,499 / ciclo','Edición de 2–4 episodios desde material del cliente. Puede alimentar los planes de contenido.'],['AI Video Lab','$999–$2,999 / ciclo','Reels cinematográficos, X-roll generativo, secuencias explicativas. Exige definir límites de iteración.'],['Content Brain Only','$499 / ciclo','Ideas y guiones sin edición. Puerta de entrada a clientes que tienen producción propia.'],['White Label Studio','Cotización B2B','Operación creativa para agencias con capacidad de producción reservada.'],['Knowledge Library','$500–$1,500 inicial','Organizar transcripciones, temas, guiones e insights como biblioteca editorial reutilizable.'],['Private Creative Studio','Hasta $9,000 / ciclo','Producción reservada para grupos o marcas con alto volumen y complejidad, sin gestionar su marketing completo.']];$('innovationGrid').innerHTML=innovations.map(x=>`<div class="card"><span class="tag">Explorar / Validar</span><h3 style="margin-top:13px">${x[0]}</h3><p><strong>${x[1]}</strong></p><p class="muted small">${x[2]}</p></div>`).join('');
function builderMarkup(client=false){const prefix=client?'c':'i';return `<div class="calc"><div><h3>1. Choose your content frequency</h3><div class="plans">${Object.entries(PLAN).map(([id,p])=>`<button type="button" aria-pressed="${state.plan===id}" class="plan ${state.plan===id?'selected':''}" onclick="choose('plan','${id}')">${id==='daily'?'<span class="tag pill">Popular</span>':id==='maximum'?'<span class="tag good pill">Recommended</span>':''}<strong>${p.name}</strong><b>${money(p.price)}</b><small>${p.frequency}</small><small>${p.total} pieces / cycle</small><small style="margin-top:9px;color:#176246">✓ Inner Circle included</small></button>`).join('')}</div><div class="divider"></div><h3>2. How would you like to create?</h3>${Object.entries(SOURCE).map(([id,s])=>`<label class="choice"><input type="radio" name="${prefix}source" ${state.source===id?'checked':''} onchange="choose('source','${id}')"><strong>${s.name} ${s.price?' · +'+money(s.price):' · Included'}</strong><span class="sub">${s.description}</span></label>`).join('')}<div class="divider"></div><h3>3. Choose your visual style</h3>${Object.entries(STYLE).map(([id,s])=>`<label class="choice"><input type="radio" name="${prefix}style" ${state.style===id?'checked':''} onchange="choose('style','${id}')"><strong>${s.name} ${s.price?' · +'+money(s.price):' · Included'}</strong><span class="sub">${s.description}</span></label>`).join('')}</div><aside class="summary"><span class="eyebrow">Your content plan</span><h3 style="margin-top:12px">${PLAN[state.plan].name}</h3><div class="price-big">${money(quote())}</div><p class="small muted">USD / every 4 weeks</p><div class="summary-line"><span>Content pieces</span><strong>${PLAN[state.plan].total}</strong></div><div class="summary-line"><span>Reels / Carousels / Memes & visuals</span><strong>${PLAN[state.plan].reels} / ${PLAN[state.plan].carousels} / ${PLAN[state.plan].memes}</strong></div><div class="summary-line"><span>Creation method</span><strong>${SOURCE[state.source].name}</strong></div><div class="summary-line"><span>Visual style</span><strong>${STYLE[state.style].name}</strong></div><div class="summary-line"><span>Inner Circle membership</span><strong style="color:#176246">Included ✓</strong></div><p class="caption" style="margin-top:15px">Client review and approval required. Content format mix may be adapted within agreed output. Some premium services billed separately.</p><div class="actions"><button class="btn" onclick="${client?"clientGo('clientProposal')":"go('proposal')"}">${client?'Crear mi propuesta':'Generar propuesta'} →</button></div></aside></div>`}
function renderBuilders(){$('builderHost').innerHTML=builderMarkup();$('clientBuilderHost').innerHTML=builderMarkup(true);renderFinance();renderProposal()}function choose(k,v){state[k]=v;saveState();renderBuilders()}
const SCENARIOS={doctor:{name:'Doctor sin tiempo',problem:'Tiene experiencia y pacientes, pero no quiere planificar ni grabarse todos los días.',plan:'daily',source:'interview',style:'dynamic',pitch:'No necesitas convertirte en creador. Prepararemos las preguntas, conversaremos contigo y transformaremos tus respuestas en 28 piezas revisables cada cuatro semanas.'},lawyer:{name:'Abogado con charlas grabadas',problem:'Tiene conferencias, entrevistas y webinars poco aprovechados.',plan:'stay',source:'own',style:'clean',pitch:'Aprovechamos el material que ya tienes para mantener una presencia consistente, respetando tus criterios de confidencialidad y publicidad profesional.'},consultant:{name:'Consultor que puede grabarse',problem:'Quiere publicar pero se queda sin ideas y no sabe estructurar mensajes.',plan:'daily',source:'guided',style:'dynamic',pitch:'Te damos temas, hooks y guiones claros. Solo necesitas grabarte; nuestra producción convierte esas ideas en una presencia diaria.'},clinic:{name:'Clínica de varios especialistas',problem:'Hay muchos conocimientos, pero falta coordinación editorial y una estética uniforme.',plan:'maximum',source:'interview',style:'cinematic',pitch:'Unificamos el conocimiento de distintos especialistas con un calendario coherente, entrevistas coordinadas y producción visual destacada.'},podcaster:{name:'Podcaster con episodios semanales',problem:'Tiene contenido largo, pero no lo aprovecha en redes.',plan:'daily',source:'own',style:'clean',pitch:'Convertimos cada episodio en una biblioteca de clips y explicaciones. La edición del episodio completo puede contratarse como servicio adicional.'}};
function renderScenario(){const s=SCENARIOS[state.scenario];$('scenarioNav').innerHTML=Object.entries(SCENARIOS).map(([id,c])=>`<button class="chip ${id===state.scenario?'active':''}" onclick="state.scenario='${id}';saveState();renderScenario()">${c.name}</button>`).join('');const total=PLAN[s.plan].price+SOURCE[s.source].price+STYLE[s.style].price;$('scenarioDetail').innerHTML=`<span class="tag">Example client</span><h2 style="margin-top:14px">${s.name}</h2><p class="muted">${s.problem}</p><div class="summary-line"><span>Frecuencia</span><strong>${PLAN[s.plan].name}</strong></div><div class="summary-line"><span>Creación</span><strong>${SOURCE[s.source].name}</strong></div><div class="summary-line"><span>Visual</span><strong>${STYLE[s.style].name}</strong></div><div class="summary-line"><span>Membresía</span><strong>Inner Circle ✓</strong></div><div class="price-big">${money(total)}</div><span class="caption">Por ciclo de 4 semanas · propuesta ilustrativa</span>`;$('scenarioPitch').textContent=s.pitch}function applyScenario(){const s=SCENARIOS[state.scenario];Object.assign(state,{plan:s.plan,source:s.source,style:s.style});saveState();renderBuilders();go('builder')}

// Atelier 02: validated local operations; no remote side effects.
function tariffData(){return {plan:Object.fromEntries(Object.entries(PLAN).map(([k,v])=>[k,v.price])),source:Object.fromEntries(Object.entries(SOURCE).map(([k,v])=>[k,v.price])),style:Object.fromEntries(Object.entries(STYLE).map(([k,v])=>[k,v.price]))}}
function setTariffs(t){for(const [group,map] of Object.entries({plan:PLAN,source:SOURCE,style:STYLE}))for(const k of Object.keys(map))map[k].price=t[group][k]}
function validTariffs(t){return t&&Object.entries({plan:PLAN,source:SOURCE,style:STYLE}).every(([g,map])=>Object.keys(map).every(k=>Number.isFinite(t[g]?.[k])&&t[g][k]>=0&&t[g][k]<=100000))&&t.source.own===0&&t.style.clean===0}
function checkedWorkspace(w){if(!w||typeof w!=='object')throw Error('Falta el espacio de trabajo');const costs={},production={};for(const k of ['costReel','costCarousel','costMeme','overhead','costGuided','costInterview','costDynamic','costCinematic']){const v=Number(w.costs?.[k]??$(k)?.value??0);if(!Number.isFinite(v)||v<0||v>100000)throw Error('Costos fuera de rango');costs[k]=v}for(const k of ['delayDays','clientCount','capacityHours']){let v=Number(w.production?.[k]??({delayDays:0,clientCount:1,capacityHours:160}[k]));const max={delayDays:90,clientCount:1000,capacityHours:10000}[k];if(!Number.isFinite(v)||v<0||v>max||(k!=='delayDays'&&v<1))throw Error('Capacidad fuera de rango');production[k]=v}production.owner=String(w.production?.owner??'').slice(0,80);const date=w.production?.cycleStart||new Date().toLocaleDateString('en-CA');production.cycleStart=/^\d{4}-\d{2}-\d{2}$/.test(date)&&!isNaN(new Date(date+'T12:00:00'))?date:new Date().toLocaleDateString('en-CA');return {costs,production,checks:Array.from({length:5},(_,i)=>w.checks?.[i]===true),batches:Array.from({length:4},(_,i)=>['Pendiente','Producción','Revisión','Aprobado','Entregado'].includes(w.batches?.[i])?w.batches[i]:'Pendiente'),journal:(Array.isArray(w.journal)?w.journal:[]).slice(0,200).map(j=>({date:String(j.date).slice(0,40),decision:String(j.decision??'').slice(0,2000),measure:String(j.measure??'').slice(0,300)}))}}
function financeCost(){const num=id=>Math.max(0,Number($(id)?.value)||0),p=PLAN[state.plan];return p.reels*num('costReel')+p.carousels*num('costCarousel')+p.memes*num('costMeme')+(state.source==='guided'?num('costGuided'):state.source==='interview'?num('costInterview'):0)+(state.style==='dynamic'?num('costDynamic'):state.style==='cinematic'?num('costCinematic'):0)+num('overhead')}
function renderFinance(){const cost=financeCost(),income=quote(),margin=income?100*(income-cost)/income:0;$('financeOutput').innerHTML=`<div class="card"><div class="eyebrow">${esc(PLAN[state.plan].name)}</div><div class="metric">${money(income)}</div><p class="small">Ingresos / ciclo · ${PLAN[state.plan].total} piezas</p><div class="summary-line"><span>Costo estimado (con overhead)</span><strong>${money(cost)}</strong></div><div class="summary-line"><span>Ingreso por pieza</span><strong>${money(income/PLAN[state.plan].total)}</strong></div></div><div class="card"><div class="eyebrow">Contribución estimada</div><div class="metric ${margin<30?'warn':''}">${money(income-cost)}</div><h3>${margin.toFixed(1)}% de margen</h3><p class="small">${income===0?'Sin ingresos; no se puede calcular el margen.':margin<0?'Este escenario pierde dinero con los costos introducidos.':margin<30?'Margen inferior al umbral de referencia de 30%; revisar costos.':'Hipótesis rentable con estos costos; validar con horas reales.'}</p></div>`}
function proposalMarkup(name){const p=PLAN[state.plan],c=SOURCE[state.source],s=STYLE[state.style];return `<div class="divider"></div><div class="eyebrow">SILVERWING — POWERED BY ABRAXAS</div><h2 data-user-content>${esc(name||(window.SWi18n?.lang==='en'?'New client':'Nuevo cliente'))}</h2><p class="lead">Your expertise. Everywhere.</p><div class="grid two"><div><h3>${p.name}</h3><p>${p.total} piezas / 4 semanas</p><p>${p.reels} Reels · ${p.carousels} carouseles · ${p.memes} memes / visuales</p></div><div><h3>${c.name}</h3><p>${c.description}</p><p><b>Acabado:</b> ${s.name}</p><p>${s.description}</p></div></div><div class="summary-line"><span>Frecuencia</span><strong>${money(p.price)}</strong></div><div class="summary-line"><span>Creación</span><strong>${money(c.price)}</strong></div><div class="summary-line"><span>Acabado</span><strong>${money(s.price)}</strong></div><h2 style="margin-top:24px">${money(quote())} <span style="font-size:15px">USD / 4 semanas</span></h2><p>✓ Inner Circle incluido con la suscripción activa. Confirmar disponibilidad de beneficios.</p><h3>Alcance y entrega</h3><p>Mix de formatos sujeto a acuerdo editorial. Guided: hasta 8 guiones por ciclo. Interview: hasta 2 entrevistas remotas de 45–60 minutos. Dynamic y Cinematic: tratamiento mejorado en 4 Reels seleccionados; el resto conserva acabado Clean.</p><p>Primer lote: objetivo de 5–8 días hábiles desde insumos completos. Lotes siguientes semanales. Una ronda consolidada de revisión por lote como regla de referencia a acordar. Los retrasos de insumos o aprobación desplazan las entregas.</p><p class="caption">Estimación comercial, pendiente de confirmación de alcance, disponibilidad y condiciones. Impuestos, pagos y contratación por acordar. No incluye gestión de pauta, garantía de alcance, viralidad ni producción presencial. La propuesta no constituye una compra. El cliente valida afirmaciones y autoriza materiales e IA.</p>`}
function renderProposal(){$('proposalBody').innerHTML=proposalMarkup($('prospect').value)}
function renderClientProposal(){$('clientProposalBody').innerHTML=proposalMarkup($('clientProspect')?.value)}
