function restoreInputs(){for(const [k,v]of Object.entries(workspace.costs))if($(k))$(k).value=v;for(const [k,v]of Object.entries(workspace.production))if($(k))$(k).value=v;renderTariffs();renderChecks();renderJournal();renderBuilders();renderScenario()}
