$('journalForm').addEventListener('submit',e=>{e.preventDefault();workspace.journal.unshift({date:new Date().toLocaleString('es'),decision:$('decision').value.trim(),measure:$('measure').value.trim()});workspace.journal=workspace.journal.slice(0,200);saveState();renderJournal();e.target.reset();toast('Decisión registrada')});
$('importData').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000)return toast('La copia supera 2 MB.');try{const d=JSON.parse(await f.text());if(d.version!==2||!validState(d.state)||!validTariffs(d.tariffs))throw Error('Formato o tarifas inválidas');const w=checkedWorkspace(d.workspace);state={plan:d.state.plan,source:d.state.source,style:d.state.style,scenario:d.state.scenario};workspace=w;setTariffs(d.tariffs);$('prospect').value=String(d.prospect||'').slice(0,120);restoreInputs();saveState();$('dataMessage').textContent='Copia importada correctamente.';toast('Datos restaurados')}catch(err){$('dataMessage').textContent='No se importó ningún dato: '+err.message}e.target.value=''});
