 pricing:[
 {title:'Precio de venta no es margen',text:'Stay Present: $399 / 12 ≈ $33.25 por pieza. Daily Authority: $799 / 28 ≈ $28.54. Maximum Visibility: $999 / 64 ≈ $15.61. Todos los importes corresponden a cuatro semanas.',why:'La caída del ingreso por pieza en Maximum Visibility obliga a comprobar horas de edición, diseño, coordinación, revisiones, insumos y capacidad simultánea. Un plan barato en términos unitarios puede perder dinero aun vendiéndose bien.',action:'Analizar rentabilidad',to:'finance'},
 {title:'Cómo construir una cotización',text:'Precio = plan base + modalidad de captura + acabado avanzado opcional. We Plan suma $500 hasta ocho guiones; Interview suma $1,000 hasta dos entrevistas; Dynamic suma $199 y Cinematic $399 sobre solo cuatro Reels seleccionados.',why:'No extiendas un acabado premium a todos los Reels sin presupuestarlo. Documenta inclusiones, exclusiones, revisiones, calendario, validaciones y supuestos antes de cerrar.',action:'Abrir Plan Builder',to:'builder'}],
 delivery:[
 {title:'Convertir una promesa en operación',text:'Días 1–2: ingreso, alcance y recepción de materiales. Días 3–4: planificación editorial. Días 5–8: primera producción y lote inicial. Días 9–28: producción y entrega por lotes, sujeto a insumos y aprobaciones.',why:'Este calendario es una hipótesis operativa, no un SLA garantizado. Cada atraso de materiales o revisión debe mover la programación de forma visible. Es preferible entregar por lotes controlados que prometer cambios ilimitados.',action:'Ver flujo de producción',to:'operations'},
 {title:'Evitar el alcance infinito',text:'Establece qué cuenta como una pieza original, adaptación o revisión. Define una ronda consolidada por lote como punto de partida a acordar; documenta formatos, número de cortes, correcciones y permisos para material generado con IA.',why:'Sin criterios de aceptación, 28 piezas pueden convertirse en decenas de trabajos extra. En contenido médico o jurídico, la revisión factual corresponde al especialista, no al editor.',action:'Revisar servicios y límites',to:'services'}],
 sales:[
 {title:'Vender un sistema, no una lista de clips',text:'Abre con la situación del cliente: «¿Qué te impide crear contenido de forma constante?». Muestra después cómo Silverwing transforma una sesión, entrevista o biblioteca existente en activos recurrentes.',why:'Un negocio compra previsibilidad, ahorro de tiempo y una calidad consistente. Evita promesas de viralidad, leads garantizados o gestión integral de marketing si no están contratadas.',action:'Abrir Sales Playbook',to:'sales'},
 {title:'Cerrar con claridad',text:'Presenta una recomendación principal, una alternativa más ligera, lo que debe aportar el cliente, el calendario orientativo, la inversión por cuatro semanas y lo que se excluye. Luego genera una propuesta específica.',why:'Demasiadas opciones frenan la compra. Haz explícito el valor de Inner Circle sin convertirlo en una compra independiente ni prometer beneficios no lanzados.',action:'Preparar propuesta',to:'builder'}],
 ideas:[
 {title:'Innovar sin dispersar la operación',text:'Podcast Studio, Podcast Launch Kit, Content Brain, paquetes visuales de IA, suscripciones white-label y servicios para miembros son líneas a experimentar; no todos son ofertas aprobadas.',why:'Antes de lanzar, exige: cliente objetivo, problema repetido, prueba de demanda, insumos, costo unitario, capacidad, precio y principal riesgo. Marca cada propuesta como hipótesis, piloto, activa o retirada.',action:'Abrir Innovation Lab',to:'innovation'},
 {title:'Tomar decisiones trazables',text:'Por cada cambio registra qué supuesto se está probando, cuál es la señal de éxito, qué límite operativo afecta y cuándo revisar el resultado. Una decisión sin criterio de validación es solo una preferencia.',why:'Una operación escalable necesita aprender de la demanda real, no sumar servicios porque parecen atractivos. Mantén una única definición de planes, precios y alcance.',action:'Abrir Decision Journal',to:'journal'}]
