(()=>{'use strict';const $=id=>document.getElementById(id),key='sw-inner-circle-beta-posts-v1',open=$('sw-pub-open'),layer=$('sw-pub'),close=$('sw-pub-close');let prev;const platforms=['instagram.com','tiktok.com','linkedin.com','youtube.com','youtu.be','facebook.com','x.com','twitter.com'];const get=()=>{try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return []}};const save=a=>localStorage.setItem(key,JSON.stringify(a));const format=d=>new Date(d).toLocaleDateString('es',{day:'2-digit',month:'short',year:'numeric'});function render(){let a=get();$('sw-pub-count').textContent=a.length;$('sw-pub-pts').textContent=a.length*10;$('sw-pub-records').replaceChildren();for(const [i,item]of a.entries()){let tr=document.createElement('tr'),values=[format(item.date),item.name||'Contenido',item.platform,'Pendiente de verificación'];values.forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});let td=document.createElement('td');let link=document.createElement('a');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Ver enlace';td.append(link);let remove=document.createElement('button');remove.type='button';remove.textContent='Eliminar';remove.style.cssText='display:block;margin-top:8px;border:0;background:transparent;color:#8c3840;text-decoration:underline';remove.addEventListener('click',()=>{let list=get();save(list.filter(x=>x.id!==item.id));render()});td.append(remove);tr.append(td);$('sw-pub-records').append(tr)}}function hide(){layer.classList.remove('open');layer.setAttribute('aria-hidden','true');prev?.focus?.()}open.addEventListener('click',()=>{prev=document.activeElement;render();layer.classList.add('open');layer.setAttribute('aria-hidden','false');close.focus()});close.addEventListener('click',hide);layer.addEventListener('click',e=>{if(e.target===layer)hide()});document.addEventListener('keydown',e=>{if(!layer.classList.contains('open'))return;if(e.key==='Escape')hide();if(e.key==='Tab'){const all=[...layer.querySelectorAll('button,a,input')].filter(x=>!x.disabled),first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});$('sw-pub-form').addEventListener('submit',e=>{e.preventDefault();const feedback=$('sw-pub-feedback');try{const input=$('sw-pub-url').value.trim(),url=new URL(input);if(url.protocol!=='https:'||!platforms.some(p=>url.hostname===p||url.hostname.endsWith('.'+p)))throw Error('Usa un enlace HTTPS de una red compatible.');const normalized=url.origin+url.pathname.replace(/\/$/,'');let records=get();if(records.some(r=>r.normalized===normalized))throw Error('Este enlace ya fue registrado.');records.push({id:Date.now()+'-'+Math.random().toString(36).slice(2),url:input,normalized,name:$('sw-pub-name').value.trim(),date:new Date().toISOString(),platform:url.hostname});save(records);$('sw-pub-form').reset();feedback.textContent='Enlace registrado localmente. Pendiente de verificación: no se han consultado estadísticas reales.';render()}catch(error){feedback.textContent=error.message}});render()})();

