(()=>{'use strict';const root=document.getElementById('sw-learning-sim');if(!root)return;const pick=id=>root.querySelector('#'+id);const data={doctor:{reason:'El profesional tiene experiencia, pero poco tiempo de grabación. Entrevistarlo reduce la fricción de capturar ideas y mantener una frecuencia diaria.',limits:'Hasta 2 entrevistas remotas por ciclo. Revisión médica de cada afirmación antes de publicar.'},lawyer:{reason:'Ya dispone de grabaciones. Conviene empezar reutilizando material aprobado antes de cobrar por guiones o entrevistas nuevas.',limits:'Revisar confidencialidad, permisos y normas de publicidad profesional. Ninguna afirmación jurídica sin validación.'},consultant:{reason:'La barrera principal es idear y estructurar. La modalidad Guided ofrece hasta 8 guiones y permite que grabe en sus propios horarios.',limits:'El cliente es responsable de grabar y entregar el material; los ocho guiones no equivalen a una pieza completa cada uno.'},clinic:{reason:'Muchos especialistas aportan temas, pero coordinación, QA y volumen requieren capacidad adicional y un calendario editorial controlado.',limits:'Máximo 64 piezas por $999 base significa aproximadamente $15.61 por pieza antes de complementos. Comprobar margen y disponibilidad.'},podcaster:{reason:'Ya existe una biblioteca de episodios; la solución inicial es recortar, organizar y adaptar fragmentos a Reels y carouseles.',limits:'La edición de episodios completos, el lanzamiento del podcast y los servicios extra no están incluidos automáticamente.'}};
const event={none:{days:0,risk:'Sin incidencias previstas. Los plazos siguen condicionados a materiales, aprobaciones y capacidad.'},missing:{days:3,risk:'Faltan insumos. No se inicia producción como si estuvieran aprobados; reprogramar al recibirlos.'},review:{days:2,risk:'Una aprobación tardía detiene la salida del lote afectado. No publicar contenido sin validación.'},scope:{days:4,risk:'Cambio de alcance: revisar el presupuesto y documentar una nueva aprobación. Cuatro días es una hipótesis, no una regla.'}};
function day(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'})}
function render(){const id=pick('sw-coach-client').value,s=SCENARIOS[id],ev=event[pick('sw-coach-event').value],extra=Math.max(0,Math.min(21,Number(pick('sw-coach-delay').value)||0)),start=pick('sw-coach-start').value;if(!start||!s)return;const days=extra+ev.days,total=PLAN[s.plan].price+SOURCE[s.source].price+STYLE[s.style].price;pick('sw-coach-plan').textContent=PLAN[s.plan].name+' · '+SOURCE[s.source].name;pick('sw-coach-price').textContent=money(total)+' USD / ciclo de 4 semanas';pick('sw-coach-reason').textContent='Por qué: '+data[id].reason;pick('sw-coach-limits').textContent='Límites: '+data[id].limits+' Acabado: '+STYLE[s.style].name+' (solo 4 Reels si es premium).';pick('sw-coach-date').textContent=day(start,5+days)+' — '+day(start,8+days);const phases=[['Onboarding (días 1–2)',day(start,1+days)+' – '+day(start,2+days)],['Editorial (días 3–4)',day(start,3+days)+' – '+day(start,4+days)],['Primer lote (días 5–8)',day(start,5+days)+' – '+day(start,8+days)],['Cierre del ciclo (día 28)',day(start,28+days)]];const box=pick('sw-coach-phases');box.replaceChildren();phases.forEach(([a,b])=>{const r=document.createElement('div'),l=document.createElement('span'),v=document.createElement('strong');l.textContent=a;v.textContent=b;r.append(l,v);box.append(r)});pick('sw-coach-risk').textContent=ev.risk+' Retraso adicional configurado: '+extra+' días. Fechas orientativas en días calendario; no son un SLA ni sustituyen una planificación laboral detallada.'}
const n=new Date();pick('sw-coach-start').value=new Date(n.getTime()-n.getTimezoneOffset()*60000).toISOString().slice(0,10);root.querySelectorAll('select,input').forEach(el=>el.addEventListener('change',render));pick('sw-coach-delay').addEventListener('input',render);pick('sw-coach-apply').addEventListener('click',()=>{const s=SCENARIOS[pick('sw-coach-client').value];Object.assign(state,{plan:s.plan,source:s.source,style:s.style});saveState();renderBuilders();go('builder')});pick('sw-coach-ops').addEventListener('click',()=>go('operations'));render();
})();

