(()=>{'use strict';const root=document.getElementById('sw-price-lab'),form=document.getElementById('tariffForm');if(!root||!form)return;const q=s=>root.querySelector(s);const price=(g,id)=>{const field=form.elements.namedItem(g+'.'+id);const n=Number(field?.value);return Number.isFinite(n)&&n>=0&&n<=100000?n:null};const fmt=n=>n===null?'Revisar':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);function render(){const wrap=q('#sw-price-lab-grid');wrap.replaceChildren();for(const [id,p] of Object.entries(PLAN)){const v=price('plan',id),delta=v===null?null:v-p.price,unit=v===null?null:v/p.total,box=document.createElement('article'),title=document.createElement('strong'),big=document.createElement('span'),desc=document.createElement('small');title.textContent=p.name;big.textContent=fmt(v);desc.textContent=p.total+' piezas · '+fmt(unit)+' / pieza. Cambio vs. guardado: '+(delta===null?'Revisar':(delta>=0?'+':'')+fmt(delta));box.append(title,big,desc);wrap.append(box)}const src=q('#sw-price-source').value,sty=q('#sw-price-style').value;const add=price('source',src),extra=price('style',sty);const out=q('#sw-price-bundle');const all=Object.entries(PLAN).map(([id,p])=>({name:p.name,amount:price('plan',id)}));out.replaceChildren();for(const row of all){const div=document.createElement('div');div.textContent=row.name+': '+(row.amount===null||add===null||extra===null?'Revisar tarifas':fmt(row.amount+add+extra))+' / 4 semanas';out.append(div)}}form.addEventListener('input',render);q('#sw-price-source').addEventListener('change',render);q('#sw-price-style').addEventListener('change',render);q('#sw-public-view').addEventListener('click',()=>window.open('https://lordjeferies.github.io/silverwing-public/','_blank','noopener,noreferrer'));q('#sw-public-catalog-export').addEventListener('click',()=>{const catalog={version:1,status:'draft',period:'4-weeks',currency:'USD',note:'Propuesta comercial sujeta a validación y aprobación. No incluye información interna.',plans:{},sources:{},styles:{}};for(const [id,p]of Object.entries(PLAN)){const amount=price('plan',id);if(amount===null)return alert('Revisa precios antes de exportar');catalog.plans[id]={name:p.name,price:amount,pieces:p.total,frequency:p.frequency}}for(const [id,x]of Object.entries(SOURCE)){const amount=price('source',id);if(amount===null)return alert('Revisa precios antes de exportar');catalog.sources[id]={name:x.name,price:amount,description:x.description}}for(const [id,x]of Object.entries(STYLE)){const amount=price('style',id);if(amount===null)return alert('Revisa precios antes de exportar');catalog.styles[id]={name:x.name,price:amount,description:x.description}}catalog.innerCircle='Included with active content plan; benefits subject to availability';const blob=new Blob([JSON.stringify(catalog,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='catalog-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});render()})();

