(()=>{'use strict';if('serviceWorker'in navigator&&location.protocol==='https:')addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{}));let pending=null;const b=document.getElementById('sw-studio-install');addEventListener('beforeinstallprompt',e=>{e.preventDefault();pending=e;b.hidden=false});b.addEventListener('click',async()=>{if(!pending)return;const p=pending;pending=null;b.hidden=true;await p.prompt()});addEventListener('appinstalled',()=>b.hidden=true)})();
